B.afU=s(["\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a \u0648\u0633\u064a\u0644\u0629 \u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0639\u0646\u0648\u0627\u0646\u0643 \u0628\u0633\u0647\u0648\u0644\u0629. \u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0635\u062d\u062a\u0647 \u0648\u0639\u0645\u0651\u0646 \u062a\u0634\u0627\u0631\u0643\u0647 \u0645\u0639\u0647\u060c \u0648\u064a\u0645\u0643\u0646\u0643 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0643\u0648\u062f \u0623\u0648 \u062d\u0630\u0641 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0641\u064a \u0623\u064a \u0648\u0642\u062a.","\u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0645\u064a\u0632\u0629 \u0627\u0644\u0645\u0643\u0648\u0646\u0629 \u0645\u0646 \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u062d\u062c\u0648\u0632\u0629 \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0648\u064a\u0645\u0643\u0646 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u064a\u0647\u0627 \u0628\u0637\u0644\u0628."],t.s)
B.a2v=new A.eX("\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a",B.afU)
B.a38=s(["\u0627\u0644\u0645\u0646\u0635\u0629 \u0623\u062f\u0627\u0629 \u0644\u062a\u0646\u0638\u064a\u0645 \u0634\u0624\u0648\u0646 \u0627\u0644\u0639\u0645\u0627\u0631\u0629 (\u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0648\u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a \u0648\u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u0635\u0648\u064a\u062a \u0648\u0627\u0644\u0635\u064a\u0627\u0646\u0629)\u060c \u0648\u0644\u0627 \u062a\u063a\u0646\u064a \u0639\u0646 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0644\u0627\u062a\u062d\u0627\u062f \u0627\u0644\u0634\u0627\u063a\u0644\u064a\u0646.","\u0631\u0626\u0627\u0633\u0629 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u062a\u0643\u0648\u0646 \u0628\u0645\u0648\u0627\u0641\u0642\u0629 \u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0642\u0642\u060c \u0623\u0648 \u0628\u0627\u0646\u062a\u062e\u0627\u0628 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0643 \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0648\u064a\u0644\u062a\u0632\u0645 \u0643\u0644 \u0639\u0636\u0648 \u0628\u062a\u0642\u062f\u064a\u0645 \u0628\u064a\u0627\u0646\u0627\u062a \u0635\u062d\u064a\u062d\u0629 \u0639\u0646 \u0648\u062d\u062f\u062a\u0647 \u0648\u0635\u0641\u062a\u0647.","\u0625\u062f\u0627\u0631\u0629 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0648\u062a\u062d\u0635\u064a\u0644\u0647\u0627 \u0648\u0635\u0631\u0641\u0647\u0627 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u0627\u062a\u062d\u0627\u062f \u0648\u0623\u0639\u0636\u0627\u0626\u0647\u060c \u0648\u0627\u0644\u0645\u0646\u0635\u0629 \u0644\u0627 \u062a\u062d\u062a\u0641\u0638 \u0628\u0647\u0627."],t.s)
